def caesar_cipher_encrypt(text, shift):
    result_chars = []

    for char in text:
        if 'a' <= char <= 'z':
            start_ord = ord('a')
            shifted_ord = (ord(char) - start_ord + shift) % 26 + start_ord
            result_chars.append(
                chr(shifted_ord),
            )
        elif 'A' <= char <= 'Z':
            start_ord = ord('A')
            shifted_ord = (ord(char) - start_ord + shift) % 26 + start_ord
            result_chars.append(
                chr(shifted_ord),
